import{af as i,z as t,J as o,ab as a}from"./chunks/framework.DG1W6mvm.js";const h=JSON.parse('{"title":"Points","description":"","frontmatter":{},"headers":[],"relativePath":"terminology/points.md","filePath":"terminology/points.md"}'),n={name:"terminology/points.md"};function l(s,e,r,d,c,u){return t(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1795004802000"},[...e[0]||(e[0]=[a('<h1 id="points" tabindex="-1">Points <a class="header-anchor" href="#points" aria-label="Permalink to &quot;Points&quot;">​</a></h1><p>Points represent a single location update from a device, and contain a number of fields that provide information about the device&#39;s state at the time the location was recorded.</p><ul><li>Identifiers: <ul><li>Point ID: Unique identifier of the point</li><li>Device ID: Device that the point relates to</li><li>Transmission ID: Hash that relates to the transmission the data was received in. Can be used to connect multiple points and readings.</li></ul></li><li>Timestamps: <ul><li><code>timestamp</code>: Time the device recorded the point, with whole-second precision. (Can be 1970 / 0 if the device didn&#39;t know the time).</li><li><code>created</code>: When the server received and processed the point, with whole-second precision.</li></ul></li><li>Location: <ul><li>Coordinates</li><li>Altitude: GPS altitude in metres above mean sea level.</li><li>Method of finding coordinates <code>gps</code>, <code>wifi</code>, <code>gsm</code></li><li>Accuracy: An estimated horizontal accuracy in metres. You can represent it as a circle of that radius around the point, but it isn’t a guaranteed boundary.</li><li>Address that has been looked up relating to the coordinates</li><li>Speed</li><li>Course: GPS course over ground in degrees. It’s most useful while moving.</li></ul></li><li>Status: <ul><li>Battery voltage</li><li>Battery percent</li><li>Average charge</li><li>Current used this transmission</li></ul></li><li>Metadata: <ul><li>GSM signal: Cellular signal-strength reading, reported as a CSQ value. Not included with every point, so a blank doesn’t by itself mean there was no network connection.</li><li>GPS Satellite count</li><li>Errors, relating to current or previous operations</li><li>Send reason</li><li>Move type</li><li>Alert type</li></ul></li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Different interfaces may expose these details in different ways, and you are encouraged to look at the individual interface documentation.</p></div><p>Other information is often submitted with points, such as <a href="./readings.html">readings</a></p>',5)])])}const m=i(n,[["render",l]]);export{h as __pageData,m as default};
